1	use std::io::{self, BufRead, Read};
2	
3	use crate::stream::raw::{InBuffer, Operation, OutBuffer};
4	
5	// [ reader -> zstd ] -> output
6	/// Implements the [`Read`] API around an [`Operation`].
7	///
8	/// This can be used to wrap a raw in-memory operation in a read-focused API.
9	///
10	/// It can wrap either a compression or decompression operation, and pulls
11	/// input data from a wrapped `Read`.
12	pub struct Reader<R, D> {
13	    reader: R,
14	    operation: D,
15	
16	    state: State,
17	
18	    single_frame: bool,
19	    finished_frame: bool,
20	}
21	
22	enum State {
23	    // Still actively reading from the inner `Read`
24	    Reading,
25	    // We reached EOF from the inner `Read`, now flushing.
26	    PastEof,
27	    // We are fully done, nothing can be read.
28	    Finished,
29	}
30	
31	impl<R, D> Reader<R, D> {
32	    /// Creates a new `Reader`.
33	    ///
34	    /// `reader` will be used to pull input data for the given operation.
35	    pub fn new(reader: R, operation: D) -> Self {
36	        Reader {
37	            reader,
38	            operation,
39	            state: State::Reading,
40	            single_frame: false,
41	            finished_frame: false,
42	        }
43	    }
44	
45	    /// Sets `self` to stop after the first decoded frame.
46	    pub fn set_single_frame(&mut self) {
47	        self.single_frame = true;
48	    }
49	
50	    /// Returns a mutable reference to the underlying operation.
51	    pub fn operation_mut(&mut self) -> &mut D {
52	        &mut self.operation
53	    }
54	
55	    /// Returns a mutable reference to the underlying reader.
56	    pub fn reader_mut(&mut self) -> &mut R {
57	        &mut self.reader
58	    }
59	
60	    /// Returns a reference to the underlying reader.
61	    pub fn reader(&self) -> &R {
62	        &self.reader
63	    }
64	
65	    /// Returns the inner reader.
66	    pub fn into_inner(self) -> R {
67	        self.reader
68	    }
69	
70	    /// Flush any internal buffer.
71	    ///
72	    /// For encoders, this ensures all input consumed so far is compressed.
73	    pub fn flush(&mut self, output: &mut [u8]) -> io::Result<usize>
74	    where
75	        D: Operation,
76	    {
77	        self.operation.flush(&mut OutBuffer::around(output))
78	    }
79	}
80	
81	impl<R, D> Reader<R, D>
82	where
83	    R: BufRead,
84	    D: Operation,
85	{
86	    /// Consume the rest of the current frame from the underlying reader.
87	    ///
88	    /// Once all the decoded data has been read, zstd may still not have
89	    /// consumed the tail of the frame: it can produce the last of the output
90	    /// before reading the frame epilogue. The underlying reader is then left
91	    /// pointing somewhere inside the frame rather than just after it.
92	    ///
93	    /// This feeds zstd the input it still needs, with no room for output, so
94	    /// the reader ends up positioned exactly at the end of the frame.
95	    ///
96	    /// It stops there: it will not start decoding whatever follows, so a
97	    /// stream of concatenated frames keeps its remaining frames, and trailing
98	    /// non-zstd data is left untouched.
99	    ///
100	    /// This is a no-op if the current frame is already complete, so it will
101	    /// not read from the underlying reader in that case.
102	    pub fn finish_frame(&mut self) -> io::Result<()> {
103	        // Only pull on the reader if zstd is actually waiting for the rest of
104	        // a frame. Otherwise this could block on a stream - a socket, say -
105	        // that has nothing more to give.
106	        if self.finished_frame || !matches!(self.state, State::Reading) {
107	            return Ok(());
108	        }
109	
110	        loop {
111	            let bytes_read = {
112	                let input = fill_buf(&mut self.reader)?;
113	                if input.is_empty() {
114	                    return Ok(());
115	                }
116	
117	                let mut src = InBuffer::around(input);
118	                // No output space: zstd will only consume the input backing
119	                // the output it has already handed us, and stops at the end of
120	                // the frame rather than starting the next one.
121	                let mut dst = OutBuffer::around(&mut [][..]);
122	
123	                let hint = self.operation.run(&mut src, &mut dst)?;
124	                if hint == 0 {
125	                    self.finished_frame = true;
126	                }
127	
