```rust
pub fn flush(&mut self, output: &mut [u8]) -> io::Result<usize>
where
    D: Operation,
{
    // An empty buffer cannot receive anything; report zero without
    // touching the operation, so no state changes and nothing is lost.
    if output.is_empty() {
        return Ok(0);
    }

    match self.state {
        State::Reading => {
            // Only deliver what the operation has already buffered:
            // do not pull more input from the reader, and do not end
